class Solution {
public:
    string solveEquation(string equation) {
        int n = equation.size();
        int eqPos = equation.find('=');

        int leftCoeff = 0, leftConst = 0;
        int rightCoeff = 0, rightConst = 0;

        parse(equation, 0, eqPos, leftCoeff, leftConst);
        parse(equation, eqPos + 1, n, rightCoeff, rightConst);

        int coeff = leftCoeff - rightCoeff;
        int constant = rightConst - leftConst;

        if (coeff == 0) {
            if (constant == 0) return "Infinite solutions";
            return "No solution";
        }
        return "x=" + to_string(constant / coeff);
    }

private:
    void parse(const string& s, int start, int end, int& coeff, int& constant) {
        int i = start;
        while (i < end) {
            int sign = 1;
            if (s[i] == '+') { sign = 1; i++; }
            else if (s[i] == '-') { sign = -1; i++; }

            int num = 0;
            bool hasDigit = false;
            while (i < end && s[i] >= '0' && s[i] <= '9') {
                num = num * 10 + (s[i] - '0');
                i++;
                hasDigit = true;
            }

            if (i < end && s[i] == 'x') {
                coeff += sign * (hasDigit ? num : 1);
                i++;
            } else {
                constant += sign * num;
            }
        }
    }
};
